  if (shouldSucceed) {
    return { success: true, data: "Data fetched successfully!" as T };
  } else {
    return { success: false, error: "Failed to fetch data." as E };
  }
}

// Safely read the result using a type guard function
function processResult<T, E>(result: Result<T, E>): T | null {
  if (result.success) {
    return result.data; // TypeScript knows 'data' exists because of the 'success' check
  } else {
    console.error(result.error);
    return null; // Or handle the error in a more sophisticated way
  }
}

